.tag-databases{background:#b45309;color:#fff}
.tag-elasticsearch{background:#059669;color:#fff}
.tag-data-eng{background:#2563eb;color:#fff}
.tag-automation{background:#7c3aed;color:#fff}
.tag-python{background:#1d4ed8;color:#fff}
.tag-node{background:#16a34a;color:#fff}
.tag-sheets{background:#15803d;color:#fff}
.tag-general{background:#6366f1;color:#fff}
.tag-js{background:#ca8a04;color:#fff}
.tag-webdev{background:#0284c7;color:#fff}
.tag-react{background:#0ea5e9;color:#fff}
.tag-tech{background:#7c3aed;color:#fff}
.tag-youtube{background:#dc2626;color:#fff}
.tag-startup{background:#ea580c;color:#fff}
.tag-design{background:#be185d;color:#fff}
.tag-productivity{background:#4f46e5;color:#fff}
.tag-life{background:#0d9488;color:#fff}
.tag-css{background:#2563eb;color:#fff}
.tag-self{background:#7c2d12;color:#fff}
.featured-card h2{font-size:1.75rem;line-height:1.3}
.author-info{display:flex;align-items:center;gap:10px;font-size:.875rem}
.avatar{width:32px;height:32px;border-radius:50%;background:var(--gold);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:.8rem;color:var(--navy);flex-shrink:0}
.author-info .time{color:var(--text-light)}

/* ARTICLE GRID */
.article-section{padding:32px 0 48px}
.article-section h3{font-size:1.25rem;margin-bottom:20px}
.article-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:24px}
.article-card{background:var(--white);border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow);transition:transform .2s,box-shadow .2s}
.article-card:hover{transform:translateY(-3px);box-shadow:0 6px 20px rgba(0,0,0,.12)}
.article-card .card-thumb{height:180px;background:var(--light);display:flex;align-items:center;justify-content:center;color:var(--text-light);font-size:.9rem;text-align:center;padding:20px;position:relative}
.article-card .card-thumb .tag-label{position:absolute;top:12px;left:12px}
.article-card .card-body{padding:16px 20px 20px}
.article-card h4{font-size:1rem;line-height:1.4;margin-bottom:12px;font-weight:700}
.article-card h4 a{color:var(--text)}
.article-card h4 a:hover{color:var(--blue);text-decoration:none}
.article-card .author-info .time{color:var(--text-light)}

/* LOAD MORE */
.load-more-wrap{text-align:center;margin:36px 0 20px}
.btn-load{background:var(--navy);color:var(--white);border:none;padding:12px 32px;font-size:.95rem;font-weight:600;border-radius:var(--radius);transition:background .2s}
.btn-load:hover{background:#1b1b32}

/* FOOTER */
.site-footer{background:var(--navy);color:rgba(255,255,255,.8);padding:48px 20px 32px;margin-top:48px}
.footer-inner{max-width:1100px;margin:0 auto}
.footer-mission{font-size:.9rem;line-height:1.7;max-width:760px;margin-bottom:28px}
.footer-guides{margin-bottom:24px}
.footer-guides h4{color:var(--gold);font-size:.85rem;text-transform:uppercase;letter-spacing:.5px;margin-bottom:10px}
.footer-guides a{color:rgba(255,255,255,.7);font-size:.85rem;margin-right:12px}
.footer-guides a:hover{color:var(--gold)}
.footer-links{display:flex;flex-wrap:wrap;gap:8px 18px;margin-bottom:20px}
.footer-links a{color:rgba(255,255,255,.6);font-size:.8rem}
.footer-links a:hover{color:var(--gold)}
.footer-copy{font-size:.78rem;color:rgba(255,255,255,.4);border-top:1px solid rgba(255,255,255,.1);padding-top:16px;margin-top:8px}

/* LEARN PAGE */
.learn-welcome{background:var(--light);padding:48px 20px;text-align:center}
.learn-welcome h1{font-size:2rem;margin-bottom:12px;color:var(--navy)}
.learn-welcome p{font-size:1.05rem;color:var(--text-light);max-width:600px;margin:0 auto}
.learn-welcome .btn-sign-in{display:inline-block;margin-top:18px;padding:10px 28px;background:var(--gold);color:var(--navy);font-weight:700;border-radius:var(--radius);font-size:.95rem}
.learn-welcome .btn-sign-in:hover{text-decoration:none;background:#e89c1c}
.curriculum-section{padding:40px 0}
.curriculum-section h2{font-size:1.5rem;margin-bottom:20px;color:var(--navy)}
.cert-list{display:grid;gap:12px}
.cert-item{display:flex;align-items:center;gap:14px;padding:16px 20px;background:var(--white);border-radius:var(--radius);box-shadow:var(--shadow);transition:transform .15s}
.cert-item:hover{transform:translateX(4px)}
.cert-icon{width:42px;height:42px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:1.3rem;flex-shrink:0}
.cert-icon.html{background:#e44d26;color:#fff}
.cert-icon.js{background:#f7df1e;color:#000}
.cert-icon.react{background:#61dafb;color:#282c34}
.cert-icon.py{background:#3776ab;color:#fff}
.cert-icon.db{background:#336791;color:#fff}
.cert-icon.api{background:#68a063;color:#fff}
.cert-icon.full{background:var(--navy);color:var(--gold)}
.cert-item span{font-weight:600;font-size:.95rem}
.challenge-section{background:var(--gold);padding:36px 20px;text-align:center;border-radius:var(--radius);margin:32px auto;max-width:1060px}
.challenge-section h2{font-size:1.3rem;margin-bottom:14px;color:var(--navy)}
.challenge-section .btn-challenge{display:inline-block;margin:6px 8px;padding:10px 22px;background:var(--navy);color:var(--white);border-radius:var(--radius);font-weight:600;font-size:.9rem}
.challenge-section .btn-challenge:hover{text-decoration:none;background:#1b1b32}
.extra-section{padding:32px 0 48px}
.extra-section h3{font-size:1.15rem;margin-bottom:14px;color:var(--navy);border-bottom:2px solid var(--gold);padding-bottom:6px;display:inline-block}
.extra-list{list-style:none;display:grid;gap:8px;margin-top:12px}
.extra-list li{padding:10px 16px;background:var(--light);border-radius:var(--radius);font-size:.9rem}
.extra-list li a{color:var(--blue);font-weight:500}
.extra-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:28px;margin-top:20px}

/* DONATE PAGE */
.donate-hero{background:linear-gradient(135deg,var(--navy) 0%,#1b1b32 100%);color:var(--white);padding:64px 20px;text-align:center}
.donate-hero h1{font-size:2.25rem;margin-bottom:16px}
.donate-hero p{font-size:1.05rem;max-width:640px;margin:0 auto;line-height:1.7;color:rgba(255,255,255,.85)}
.donation-form-section{max-width:600px;margin:-40px auto 40px;padding:32px;background:var(--white);border-radius:12px;box-shadow:0 8px 32px rgba(0,0,0,.12);position:relative;z-index:2}
.amount-tabs{display:flex;gap:10px;margin-bottom:20px;justify-content:center}
.amount-tab{padding:12px 24px;font-size:1.1rem;font-weight:700;border:2px solid var(--gray);border-radius:var(--radius);background:var(--white);color:var(--text);transition:all .2s}
.amount-tab.active,.amount-tab:hover{border-color:var(--gold);background:var(--gold);color:var(--navy)}
.donation-desc{text-align:center;font-size:.95rem;color:var(--text-light);margin-bottom:20px;min-height:44px}
.btn-donate{display:block;width:100%;padding:14px;background:var(--gold);color:var(--navy);border:none;font-size:1.1rem;font-weight:800;border-radius:var(--radius);transition:background .2s}
.btn-donate:hover{background:#e89c1c}
.donation-sub{text-align:center;font-size:.82rem;color:var(--text-light);margin-top:12px}
.benefits-section{padding:48px 0}
.benefits-section h2{font-size:1.5rem;color:var(--navy);margin-bottom:20px;text-align:center}
.benefit-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px;max-width:900px;margin:0 auto}
.benefit-card{padding:24px;background:var(--light);border-radius:var(--radius);text-align:center}
.benefit-card .b-icon{font-size:2rem;margin-bottom:10px}
.benefit-card p{font-size:.9rem;color:var(--text)}
.initiatives-section{background:var(--light);padding:48px 20px}
.initiatives-section h2{font-size:1.5rem;color:var(--navy);margin-bottom:20px;text-align:center}
.initiative-list{max-width:700px;margin:0 auto;display:grid;gap:12px}
.initiative-list li{padding:14px 20px;background:var(--white);border-radius:var(--radius);font-size:.95rem;display:flex;align-items:center;gap:10px;box-shadow:var(--shadow)}
.initiative-list li::before{content:"";display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--gold);flex-shrink:0}
.achievements-section{padding:48px 0;text-align:center}
.achievements-section h2{font-size:1.5rem;color:var(--navy);margin-bottom:24px}
.stat-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:20px;max-width:900px;margin:0 auto}
.stat-card{padding:24px;border-radius:var(--radius);border:1px solid var(--gray)}
.stat-card .num{font-size:2rem;font-weight:800;color:var(--navy);display:block}
.stat-card .label{font-size:.85rem;color:var(--text-light);margin-top:4px}
.faq-section{padding:48px 0;max-width:760px;margin:0 auto}
.faq-section h2{font-size:1.5rem;color:var(--navy);margin-bottom:20px;text-align:center}
.faq-item{border-bottom:1px solid var(--gray)}
.faq-q{width:100%;padding:16px 0;background:none;border:none;font-size:.95rem;font-weight:600;text-align:left;display:flex;justify-content:space-between;align-items:center;color:var(--text)}
.faq-q::after{content:"+";font-size:1.3rem;font-weight:400;color:var(--text-light);transition:transform .2s}
.faq-item.open .faq-q::after{content:"\2212"}
.faq-a{max-height:0;overflow:hidden;transition:max-height .3s ease;font-size:.9rem;color:var(--text-light);line-height:1.7}
.faq-item.open .faq-a{max-height:200px;padding-bottom:16px}

/* TAG PAGES */
.tag-hero{padding:40px 20px;text-align:center}
.tag-hero h1{font-size:2rem;color:var(--navy);text-transform:uppercase;letter-spacing:1px}
.tag-hero .post-count{font-size:1rem;color:var(--text-light);margin-top:4px}
.popular-tags{padding:0 20px 24px;max-width:1100px;margin:0 auto;overflow-x:auto}
.popular-tags h3{font-size:1rem;margin-bottom:12px;color:var(--text-light)}
.tags-row{display:flex;gap:10px;flex-wrap:nowrap;padding-bottom:8px}
.tags-row .ptag{display:inline-flex;align-items:center;gap:6px;padding:6px 14px;background:var(--light);border-radius:20px;font-size:.82rem;white-space:nowrap;color:var(--text);font-weight:500;border:1px solid var(--gray);text-decoration:none;transition:background .15s}
.tags-row .ptag:hover{background:var(--gold);color:var(--navy);border-color:var(--gold);text-decoration:none}
.tags-row .ptag .count{font-weight:400;color:var(--text-light)}

/* RESPONSIVE */
@media(max-width:768px){
  .header-inner{flex-wrap:wrap}
  .search-bar{order:3;max-width:100%;flex-basis:100%;margin-top:8px}
  .nav-links{display:none}
  .hamburger{display:block}
  .featured-card{flex-direction:column;min-height:auto}
  .featured-card .thumb{min-height:200px;min-width:100%}
  .featured-card .content{padding:24px 20px}
  .featured-card h2{font-size:1.3rem}
  .article-grid{grid-template-columns:1fr}
  .amount-tabs{flex-wrap:wrap}
  .stat-grid{grid-template-columns:repeat(2,1fr)}
  .benefit-grid{grid-template-columns:1fr}
  .extra-grid{grid-template-columns:1fr}
}
